import {TAX_SCHEDULES} from './tax.js';
import {scenarioMetrics,changedAssumptions} from './comparison.js';
import {LABELS} from './content.js';
export const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dollars=n=>n===null?'No finite limit':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);

export function taxControls(state,{fields,help}){
 const h=state.home;
 const select=(key,label,options)=>`<div class="field"><div class="field-label"><label for="h-${key}">${label}</label>${help('wageTax')}</div><select id="h-${key}" class="planning-select" data-tax-select="${key}">${options.map((name,i)=>`<option value="${i}" ${h[key]===i?'selected':''}>${name}</option>`).join('')}</select></div>`;
 return `<div class="tax-controls">${select('taxMode','How should we estimate taxes?',['My effective tax rates','2026 wage-tax estimate'])}${h.taxMode===1?`<div class="fields">${select('filingStatus','Tax filing status',TAX_SCHEDULES.map(s=>s.name))}${h.filingStatus===1?select('wageEarners','Adults earning these wages',['One wage earner','Two wage earners']):''}</div>${fields([...(h.filingStatus===1&&h.wageEarners===1?['secondEarnerPct']:[]),'stateTaxRate'])}<p class="inline-note">2026 federal brackets, standard deduction, and wage payroll taxes. Wages only; no credits, itemized or additional deductions, non-wage income, or pre-tax health benefits. State/local tax is your effective-rate assumption. Not a tax return.</p>`:fields(['incomeTaxRate','payrollTaxRate'])+'<p class="inline-note">Your average income-tax and payroll-tax rates. Calibrate with your pay records; brackets and wage caps are not calculated in this mode.</p>'}</div>`;
}

const METRICS=[['Estimated maximum home price','homeBudget'],['Required gross income / year','requiredIncome'],['Target home price','targetPrice'],['Upfront cash shortfall','cashGap'],['Remaining / month · current housing','currentRemaining'],['Remaining / month · proposed home','proposedRemaining'],['Net worth today','netWorth'],['Future net worth · nominal dollars','futureWorth'],["Future net worth · today's dollars",'futureReal'],['Unfunded forecast withdrawals','unfunded']];
export function comparisonTable(left,right){
 const a=scenarioMetrics(left),b=scenarioMetrics(right),changes=changedAssumptions(left,right);
 const horizon=m=>`Age ${m.targetAge} · ${m.years} years`;
 return `<p class="inline-note">Saved snapshots. Home results include each scenario’s stress test; Budget uses base spending. Comparisons never load or change your current inputs.</p>${a.targetAge!==b.targetAge||a.years!==b.years?'<p class="comparison-warning">Different forecast horizons: future amounts are not directly comparable.</p>':''}<div class="table-scroll"><table class="comparison-table"><thead><tr><th scope="col">Measure</th><th scope="col">Plan A</th><th scope="col">Plan B</th><th scope="col">B minus A</th></tr></thead><tbody><tr><th scope="row">Projection horizon</th><td>${horizon(a)}</td><td>${horizon(b)}</td><td>—</td></tr><tr><th scope="row">Home stress test</th><td>${a.stress?'On':'Off'}</td><td>${b.stress?'On':'Off'}</td><td>—</td></tr><tr><th scope="row">Tax model</th><td>${a.taxMode?'2026 wages':'Effective rates'}</td><td>${b.taxMode?'2026 wages':'Effective rates'}</td><td>—</td></tr>${METRICS.map(([label,key])=>`<tr><th scope="row">${label}</th><td>${dollars(a[key])}</td><td>${dollars(b[key])}</td><td>${a[key]===null||b[key]===null?'—':dollars(b[key]-a[key])}</td></tr>`).join('')}</tbody></table></div><details class="comparison-differences"><summary>${changes.length} changed input${changes.length===1?'':'s'}</summary><p class="inline-note">Raw stored values use annual income, monthly expenses and percentage rates. Forecast balances, assumptions and contributions are separate from the home and Budget spending plan.</p><div class="table-scroll"><table><thead><tr><th>Input</th><th>Plan A</th><th>Plan B</th></tr></thead><tbody>${changes.map(c=>`<tr><th>${escapeHTML(LABELS[c.key]||c.key)}</th><td>${escapeHTML(c.left??'Not listed')}</td><td>${escapeHTML(c.right??'Not listed')}</td></tr>`).join('')||'<tr><td colspan="3">The modeled inputs are identical.</td></tr>'}</tbody></table></div></details>`;
}

export function coachView(c,settings){
 return `<div class="diagnosis-heading ${c.mood}"><div class="diagnosis-sprite ${c.mood}" role="img" aria-label="${c.mood} cartoon Dave"></div><div><p class="eyebrow">YOUR CARTOON REALITY CHECK</p><p class="diagnosis-quote">${escapeHTML(c.quote)}</p><p>${escapeHTML(c.intro)}</p></div></div><p class="inline-note">Playful parody · unaffiliated with Dave Ramsey or Ramsey Solutions. ${c.example?'Example plan; replace the gray inputs first.':c.exampleCount?`${c.exampleCount} household settings still use starting examples. Check them before relying on this review.`:''}</p><div class="diagnosis-findings">${c.findings.map((f,i)=>`<article class="diagnosis-finding severity-${f.severity}"><small>${escapeHTML(f.rule)} · ${f.severity===3?'Priority':f.severity===2?'Review':'Consider'}</small><h3>${escapeHTML(f.title)}</h3><p>${escapeHTML(f.detail)}</p><button class="btn" data-diagnosis-action="${i}">Adjust this <span aria-hidden="true">→</span></button></article>`).join('')||`<p>${escapeHTML(c.positive||'Fill in the worksheet, then ask again.')}</p>`}</div><details class="coach-settings"><summary>Adjust Dave’s planning preferences</summary><p class="inline-note">These only change his comments. Your calculator answers stay the same.</p><label class="coach-checkbox"><input id="coach-ramsey" type="checkbox" ${settings.ramsey?'checked':''}> Include Ramsey’s stricter preferences</label><div class="fields"><label class="field" for="coach-car">Flag car payments above this share of take-home (%)<input class="planning-select" id="coach-car" type="number" min="1" max="50" step="any" value="${settings.carPaymentPct}"></label><label class="field" for="coach-emergency">Emergency-fund target (months of core spending)<input class="planning-select" id="coach-emergency" type="number" min="1" max="12" step="any" value="${settings.emergencyMonths}"></label></div><p class="inline-note">The 15% car-payment trigger is an adjustable app preference. The emergency target starts at three months. Neither is a personal recommendation.</p><p id="coach-setting-error" role="status"></p><button class="btn dark" id="apply-coach-settings">Update Dave’s review</button><p class="inline-note">Preferences are kept with named saves. The character uses local rules; no financial entries are sent to an AI.</p><p class="source-links"><a href="https://www.ramseysolutions.com/real-estate/how-much-house-can-i-afford" target="_blank" rel="noopener noreferrer">Ramsey housing preference ↗</a> · <a href="https://www.ramseysolutions.com/saving/car-payment-calculator" target="_blank" rel="noopener noreferrer">Vehicle-value preference ↗</a> · <a href="https://www.ramseysolutions.com/debt/how-the-debt-snowball-method-works" target="_blank" rel="noopener noreferrer">Debt snowball ↗</a></p></details>`;
}
